    "question_text": "الأداء المنزلي (٤): قارن بين الخطأ في المبدأ المحاسبي والخطأ المتكافئ/المتوازن من حيث المفهوم وكيفية حدوثه وأثره على توازن ميزان المراجعة، وهل يكشفه ميزان المراجعة، مع تقديم مثال وطريقة التصحيح لكل منهما، مستعينًا بالجدول المقارن.",
