    "answer": "• وجه المقارنة:\n١. المفهوم:\n   - خطأ المبدأ: خرق القواعد والمعايير المحاسبية بالخلط بين الحسابات الرأسمالية (الأصول) والحسابات الإيرادية (المصروفات والإيرادات).\n   - الخطأ المتكافئ: خطآن أو أكثر مستقلان وغير مقصودين، يعوض أثر أحدهما أثر الآخر بالصدفة في الجانبين.\n٢. كيفية حدوثه:\n   - خطأ المبدأ: تسجيل شراء أصل رأسمالي في حساب مصروف إيرادي أو العكس نتيجة ضعف الفهم المهني.\n   - الخطأ المتكافئ: وقوع زيادة أو نقص حسابي في جانب مدين يقابله بالصدفة زيادة أو نقص مساوٍ في جانب دائن لحسابات أخرى منفصلة.\n٣. أثره على توازن الميزان:\n   - خطأ المبدأ: لا يؤثر على التوازن (يظل الميزان متوازناً).\n   - الخطأ المتكافئ: لا يؤثر على التوازن (يظل الميزان متوازناً).\n٤. هل يكشفه ميزان المراجعة؟:\n   - خطأ المبدأ: لا يكشفه إطلاقاً.\n   - الخطأ المتكافئ: لا يكشفه إطلاقاً.\n٥. مثال توضيحي:\n   - خطأ المبدأ: شراء آلة إنتاجية بمبلغ 15,000 ج وتسجيلها في حساب مصروفات الصيانة.\n   - الخطأ المتكافئ: زيادة جمع حساب المبيعات بمبلغ 2,000 ج (دائن) وزيادة جمع حساب الأجور بمبلغ 2,000 ج (مدين).\n٦. طريقة التصحيح:\n   - خطأ المبدأ: إجراء قيد تسوية يحمل الحساب الصحيح ويلغي الحساب الخاطئ (من حـ/ الآلات إلى حـ/ مصروفات الصيانة).\n   - الخطأ المتكافئ: اكتشاف وتصحيح كل خطأ على حدة بصورة مستقلة لإعادة الحسابات لأرصدتها الحقيقية.",
