      "3. فحص الخطأ 3: تضخيم مخزون 20,000 ← خفض تكلفة وتضخيم ربح بـ 20,000 وتضخيم أصول بـ 20,000.",
      "4. فحص الخطأ 4: إغفال مشتريات 15,000 ← تضخيم ربح بـ 15,000 ونقص التزامات بـ 15,000.",
