    "answer": "المقارنة المنهجية بين مجمل الربح وصافي الربح:\n1. مجمل الربح (Gross Profit):\n   - مكان الاستخراج: الرصيد المرحل من حساب المتاجرة (أو المرحلة الأولى من قائمة الدخل).\n   - المعادلة: صافي إيراد المبيعات − تكلفة البضاعة المباعة.\n   - الهدف والدلالة: قياس كفاءة النشاط التجاري الأساسي الصرف، ومدى قدرة سياسة التسعير وإدارة المخزون على تحقيق عائد يغطي تكلفة الشراء المباشرة.\n2. صافي الربح (Net Profit):\n   - مكان الاستخراج: الرصيد الختامي لحساب الأرباح والخسائر المنقول إلى رأس المال بحقوق الملكية.\n   - المعادلة: مجمل الربح + الإيرادات الأخرى والأرباح الرأسمالية − كافة المصروفات التشغيلية والبيعية والإدارية والتمويلية والاستهلاكات.\n   - الهدف والدلالة: قياس المحصلة النهائية لكافة عمليات وأنشطة المنشأة، والقدرة الصافية على تنمية حقوق الملكية وتحقيق عائد للمالك.",
