    "answer": "تعد قيود التسوية التطبيق العملي الأبرز لأساس الاستحقاق ومبدأ المقابلة للأسباب الآتية:\n1. أساس الاستحقاق (Accrual Basis): يفرض الاعتراف بالإيرادات عند اكتسابها وتحقق واقعة بيع السلعة أو أداء الخدمة (سواء قُبضت نقداً أم لا)، وتحميل المصروفات التي استُنفدت في سبيل النشاط (سواء سُددت نقداً أم لا). وقيود التسوية هي الأداة الفنية التي تعزل ما يخص الفترة من إيرادات ومصروفات عما تم تحصيله أو دفعه فعلياً.\n2. مبدأ المقابلة (Matching Principle): يوجب مقابلة إيرادات الفترة المحاسبية بكافة التكاليف والمصروفات التي أُنفقت لتحقيق تلك الإيرادات تحديداً؛ وبدون قيود التسوية (للمصروفات المستحقة والمقدمة والإهلاك والديون المشكوك فيها) تختلط إيرادات ومصروفات فترات متعددة وتفقد القوائم المالية عدالتها ومصداقيتها.",
