    "answer": "1. معادلة رأس المال آخر الفترة (Ending Capital):\n   - **رأس المال آخر الفترة = رأس المال أول الفترة + الاستثمارات الإضافية (زيادات رأس المال) + صافي الربح (أو − صافي الخسارة) − المسحوبات الشخصية**.\n2. بيان الأثر المالي للأرباح والمسحوبات:\n   - **أثر الأرباح (صافي الربح)**: أثر إيجابي طردي يمثل العائد الاقتصادي المحقق من تشغيل أموال المنشأة، ويعمل على تنمية وزيادة حقوق الملكية وثروة المالك المستثمرة.\n   - **أثر المسحوبات الشخصية**: أثر سلبي عكسي يمثل استرداداً وتخفيضاً جزئياً لرأس المال لاستخدامات المالك الخاصة، ويؤدي مباشرة إلى إنقاص حقوق الملكية وتخفيض السيولة المتاحة للمنشأة.",
